const moments=[
{time:101,label:'01:41',title:'The language of imitation',short:'Setting the scene',type:'FOUNDATION',color:'green',slide:2,summary:'We learn a policy <b>π</b> from an expert <b>π*</b>. We can ask what action the expert would take, but we cannot directly observe their cost function.',formula:'Learn the action.<br>Not the intention.',intuition:'The expert tells us what to do in a state. A surrogate loss measures how often our policy disagrees. The horizon T tells us how many steps the task lasts.',connection:'Defines the policies we compare',quote:'we’re going to assume that we can query the expert, and by query, what we mean is that we can ask the expert, hey, like, here’s the state, give us an action.',quoteTime:'01:41 onward'},
{time:440,label:'07:20',title:'Copy the expert. What could go wrong?',short:'Behavior cloning',type:'CONCEPT',color:'green',slide:3,summary:'Collect expert demonstrations, then train a supervised model to predict the expert’s actions. Simple and powerful — until <b>the learner encounters states the expert never visited.</b>',formula:'Observe → imitate',intuition:'Use classification for discrete actions and regression for continuous actions. This works best with short tasks or broad expert coverage.',connection:'Assumes the training data will be enough',quote:'the distribution of states that the learner visits depends on its policy.',quoteTime:'After 13:30; exact sentence timing unavailable'},
{time:733,label:'12:13',title:'A small mistake. A different world.',short:'Distribution shift',type:'KEY CONCEPT',color:'green',slide:4,summary:'The expert’s training states and the learner’s test states come from <b>different distributions</b>. The learner’s own actions change what it sees next.',formula:'dπ* ≠ dπ̂',intuition:'Imagine learning to drive only from perfect driving. If you drift toward the shoulder, you may never have seen an example of how to recover.',connection:'Explains why errors stop being independent',quote:'we trained on one distribution, right? This D here, which is, you know, the dataset distribution. But… the distribution that the agent sees is a different one.',quoteTime:'12:13'},
{time:1080,label:'≈18:00',title:'One mistake becomes many.',short:'Compounding errors',type:'KEY INSIGHT',color:'peach',slide:5,summary:'A small steering error takes the learner off the expert’s path. Now it’s in unfamiliar territory, where <b>each mistake makes the next one more likely.</b>',formula:'Small error.<br>Snowball effect.',intuition:'The model has learned how to stay on the road, but not how to get back onto it. Good performance on expert data doesn’t guarantee good behavior on its own.',connection:'Turns distribution shift into accumulating cost',quote:'There’s just no data coverage there, so it didn’t know what to do.',quoteTime:'Between 13:30 and 28:26; estimated moment'},
{time:1380,label:'≈23:00',title:'Why the cost grows quadratically',short:'The quadratic bound',type:'THEORY',color:'peach',slide:7,summary:'Over a horizon of T steps, a mistake can affect every remaining step. In the worst case, the extra expected cost scales as <b>T²ε</b>, not just Tε.',formula:'J(π̂) ≤ J(π*) + T²ε',intuition:'ε measures disagreement on expert states. T opportunities to go wrong, each with up to T steps of consequences, gives the quadratic intuition. This is a worst-case bound.',connection:'Motivates collecting different training data',quote:'And so again, the intuition here is just this snowball effect',quoteTime:'Between 13:30 and 28:26; estimated moment'},
{time:1718,label:'28:38',title:'Learn where you actually go.',short:'DAgger',type:'ALGORITHM',color:'lavender',slide:9,summary:'Run the learner, ask the expert to label the states it actually visits, then <b>aggregate the data and retrain</b>. Repeat to close the distribution gap.',formula:'Roll out → query<br>→ aggregate → retrain',intuition:'The states come from the learner. The correct action labels still come from the expert. Early expert mixing can keep the collected data useful.',connection:'Addresses the mismatch at its source',quote:'as the agent runs, you take the states it visits, and you query the expert, hey, what would have you done?',quoteTime:'28:38'},
{time:3120,label:'≈52:00',title:'Can we get back on track?',short:'Recoverability',type:'BIG PICTURE',color:'green',slide:13,summary:'DAgger’s benefit depends on <b>how recoverable the environment is</b>. If one action causes irreversible damage, even an expert may be unable to undo it.',formula:'Recovery changes<br>the guarantee.',intuition:'When the single-mistake cost u stays constant, the bound scales linearly in T. When u grows with T, the guarantee can become quadratic again.',connection:'Reveals the limits of the proposed solution',quote:'once you got off track, the expert can’t get you back on track.',quoteTime:'Before 01:00:35; estimated moment'}];
let selected=3, elapsed=1990, playing=false,speed=1,tab='timeline';let saved=[];let completed=[];try{saved=JSON.parse(localStorage.getItem('recall-saved')||'[]');completed=JSON.parse(localStorage.getItem('recall-tasks')||'[]')}catch{}const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];const fmt=s=>`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;const slide=n=>`assets/slide-${String(n).padStart(2,'0')}.png`;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),2400)}
function persist(){try{localStorage.setItem('recall-saved',JSON.stringify(saved));localStorage.setItem('recall-tasks',JSON.stringify(completed))}catch{toast('Browser storage unavailable; changes last for this session.')}}
function available(){const ids=moments.map((m,i)=>m.time<=elapsed?i:-1).filter(i=>i>=0);return ids.length?ids:[0]}
function renderTimeline(){const ids=available();$('#timelineTrack').innerHTML=ids.map(i=>{const m=moments[i];return `<button class="moment ${selected===i?'selected':''}" data-id="${i}" data-color="${m.color}" aria-pressed="${selected===i}"><div class="moment-box"><div class="tag">${m.type}<span>${selected===i?'↗':'✧'}</span></div><h3>${m.short}</h3><div class="card-bottom"><span>Slide ${String(m.slide).padStart(2,'0')}</span><span>${saved.includes(i)?'◆':'↗'}</span></div></div><span class="moment-point"></span><time>${m.label}</time></button>`}).join('');$$('.moment').forEach(b=>b.onclick=()=>select(+b.dataset.id));$('#prev').disabled=selected<=0;$('#next').disabled=selected>=ids.at(-1)}
function select(i,scroll=true){selected=i;renderTimeline();renderDetail();if(scroll)$(`.moment[data-id="${i}"]`)?.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'})}
function renderDetail(){const m=moments[selected];const d=$('#detail');d.classList.remove('animate');void d.offsetWidth;d.classList.add('animate');d.innerHTML=`<div class="detail-top"><span class="pill">${m.type}</span><span class="detail-time">${m.label} &nbsp; / &nbsp; MOMENT ${String(selected+1).padStart(2,'0')}</span></div><h2 class="detail-title">${m.title}</h2><p class="detail-summary">${m.summary}</p><div class="visual-row"><button class="slide-button" id="expandSlide" aria-label="Expand slide ${m.slide}"><img src="${slide(m.slide)}" alt="Lecture slide ${m.slide}: ${m.short}"><span class="slide-caption"><span>FROM YOUR SLIDES · ${String(m.slide).padStart(2,'0')} / 13</span><span>⤢</span></span></button><div class="intuition"><div class="eyebrow">✧ &nbsp; THE INTUITION</div><h4>${m.formula}</h4><p>${m.intuition}</p><div class="annotation">Grounded in this lecture’s slides & transcript</div></div></div><div class="detail-actions"><button id="explain">✧ &nbsp; Explain simply</button><button id="showTranscript">≋ &nbsp; In the lecture</button><button id="save">${saved.includes(selected)?'◆ Saved':'◇ Save moment'}</button></div>`;$('#expandSlide').onclick=()=>showSlide(m.slide,m.short);$('#explain').onclick=()=>openModal(`<div class="eyebrow">ONE IDEA, MADE SIMPLE</div><h2>${m.title}</h2><p>${m.intuition}</p><div class="empty-note">${m.summary}</div><div class="modal-footer"><button class="primary" id="backMoment">Got it. Back to the lecture ↗</button></div>`),$('#showTranscript').onclick=()=>openModal(`<div class="eyebrow">FROM THE LECTURE TRANSCRIPT</div><h2>${m.short}</h2><blockquote>“${m.quote}”</blockquote><p>Prof. Scott Niekum · ${m.quoteTime}</p><p>Excerpt from the local September 15 transcript. Capitalization and punctuation lightly cleaned for readability.</p>`);$('#save').onclick=()=>{saved=saved.includes(selected)?saved.filter(x=>x!==selected):[...saved,selected];persist();renderDetail();renderTimeline();toast(saved.includes(selected)?'Moment saved to your materials.':'Moment removed from saved materials.')};const prev=Math.max(0,selected-1),next=Math.min(available().at(-1),selected+1);$('#connections').innerHTML=[...new Set([prev,selected,next])].map(i=>`<button class="connection ${i===selected?'current':''}" data-connect="${i}">${moments[i].short}<small>${moments[i].connection}</small></button>`).join('');$$('[data-connect]').forEach(b=>b.onclick=()=>select(+b.dataset.connect))}
function showSlide(n,title){openModal(`<div class="eyebrow">690S · ORIGINAL LECTURE MATERIAL</div><h2>${title}</h2><img src="${slide(n)}" alt="Full lecture slide ${n}"><p>Slide ${n} of 13 · Limitations of Behavior Cloning · Prof. Scott Niekum</p><div class="modal-footer"><button class="primary" id="slidePrev" ${n===1?'disabled':''}>← Previous</button><button class="primary" id="slideNext" ${n===13?'disabled':''}>Next slide →</button></div>`);$('#slidePrev').onclick=()=>showSlide(n-1,'Lecture slides');$('#slideNext').onclick=()=>showSlide(n+1,'Lecture slides')}
function openModal(html){$('#modalContent').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();$('#backMoment')?.addEventListener('click',()=>$('#modal').close())}$('#closeModal').onclick=()=>$('#modal').close();$('#modal').onclick=e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}};
function setTab(name){tab=name;$$('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===name);b.setAttribute('aria-selected',b.dataset.tab===name)});['timeline','map','resources','tasks'].forEach(n=>$(`#${n}-view`).hidden=n!==name);if(name==='map')renderMap();if(name==='resources')renderResources();if(name==='tasks')renderTasks()}
$$('[data-tab]').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));$$('[data-open-map]').forEach(b=>b.onclick=()=>setTab('map'));
function renderMap(){const pos=[[110,80],[360,80],[610,80],[610,225],[360,225],[110,225],[360,370]];const labels=['sets up','trained on','drifts into','compounds','motivates','limited by'];$('#map-view').innerHTML=`<div class="eyebrow">YOUR EVOLVING KNOWLEDGE MAP</div><h2>Follow the why, not just the what.</h2><p class="subtext">Each connection tells a story. Select an idea to return to its moment in the lecture.<br>Solid nodes have been discussed. Faded nodes are upcoming in this replay.</p><div class="map-canvas"><svg viewBox="0 0 830 450" role="group" aria-label="Concept connections from imitation through DAgger and recoverability">${pos.slice(1).map((p,i)=>{const q=pos[i];return `<path d="M${q[0]},${q[1]} L${p[0]},${p[1]}" stroke="#bbcba6" stroke-width="1.5" stroke-dasharray="${i===5?'5 5':''}"/><text x="${(p[0]+q[0])/2}" y="${(p[1]+q[1])/2-10}" text-anchor="middle" fill="#95a483" font-size="9">${labels[i]}</text>`}).join('')}${moments.map((m,i)=>`<g class="graph-node" data-node="${i}" tabindex="0" role="button" aria-label="${m.short}" transform="translate(${pos[i][0]-90},${pos[i][1]-30})" opacity="${m.time<=elapsed?1:.4}"><rect width="180" height="60" rx="10" fill="${m.color==='peach'?'#f3e4d4':m.color==='lavender'?'#e9e1f3':'#e6eddc'}" stroke="#c6d4b6"/><text x="90" y="25" text-anchor="middle" fill="#3e5837" font-size="12">${m.short}</text><text x="90" y="44" text-anchor="middle" fill="#8a9c77" font-size="9">${m.label} · ${m.time<=elapsed?'Explore moment ↗':'Upcoming · jump ahead'}</text></g>`).join('')}</svg></div>`;$$('[data-node]').forEach(b=>{const go=()=>{const i=+b.dataset.node;if(moments[i].time>elapsed){elapsed=moments[i].time;updateClock()}setTab('timeline');select(i)};b.onclick=go;b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go()}}})}
function renderResources(){$('#resources-view').innerHTML=`<div class="eyebrow">ALL THE CONTEXT, IN ONE PLACE</div><h2>Your lecture, connected.</h2><p class="subtext">Original slide visuals and the moments you want to come back to.</p><div class="resource-grid">${[{slide:1,title:'The lecture deck',desc:'13 original slides · Browse the complete lecture',id:1},{slide:5,title:'The driving example',desc:'Why small errors push us off distribution',id:5},{slide:9,title:'Inside DAgger',desc:'The rollout, query, and retrain loop',id:9}].map(r=>`<button class="resource" data-slide="${r.id}"><img src="${slide(r.slide)}" alt="${r.title}"><h3>${r.title}</h3><p>${r.desc}</p><span>Open slides ↗</span></button>`).join('')}</div><h2 style="font-size:20px;margin-top:32px">Saved moments <small style="font-size:12px;color:#9aa88b">${saved.length}</small></h2>${saved.length?`<div class="task-list">${saved.map(i=>`<button class="resource" data-saved="${i}"><h3>${moments[i].title}</h3><p>${moments[i].label} · ${moments[i].short} ↗</p></button>`).join('')}</div>`:'<p class="subtext">Select “Save moment” on the timeline to keep an idea here.</p>'}`;$$('[data-slide]').forEach(b=>b.onclick=()=>showSlide(+b.dataset.slide,'Lecture slides'));$$('[data-saved]').forEach(b=>b.onclick=()=>{const i=+b.dataset.saved;elapsed=Math.max(elapsed,moments[i].time);updateClock();setTab('timeline');select(i)})}
function renderTasks(){const tasks=[['Explain the distribution mismatch','Why does a learner visit different states from an expert, even after learning from expert demonstrations?'],['Connect DAgger to the quadratic bound','Explain how collecting expert labels on learner-visited states addresses compounding errors.'],['Understand when recovery is possible','Compare a correctable lane drift with missing the only bridge across a river. How does u affect the guarantee?']];$('#tasks-view').innerHTML=`<div class="eyebrow">TURN IDEAS INTO UNDERSTANDING</div><h2>A few things to take with you.</h2><p class="subtext">Study prompts based on the instructor’s closing takeaways. Previewing the complete lecture.</p><div class="task-list">${tasks.map((t,i)=>`<label class="task"><input type="checkbox" data-task="${i}" ${completed.includes(i)?'checked':''}><div><h3>${t[0]}</h3><p>${t[1]}</p><small>Study suggestion · No due date · Lecture closing remarks before 01:00:35</small></div></label>`).join('')}</div><div class="empty-note"><b>No assignment deadline extracted from this lecture.</b><br>These are study suggestions, not submitted coursework or confirmed assignments. In a connected version, explicit announcements and deadlines would appear here with their source.</div>`;$$('[data-task]').forEach(b=>b.onchange=()=>{const i=+b.dataset.task;completed=b.checked?[...new Set([...completed,i])]:completed.filter(x=>x!==i);persist()})}
$('#catchup').onclick=()=>{const ids=available().filter(i=>moments[i].time>=elapsed-900).slice(-3);if(!ids.length)ids.push(0);openModal(`<div class="eyebrow">✧ YOUR QUICK REWIND · ${fmt(Math.max(0,elapsed-900))}–${fmt(elapsed)}</div><h2>You’re only a few ideas away.</h2><p>Here’s the thread leading into the current discussion.</p>${ids.map((i,j)=>`<div class="recap-step"><span class="recap-num">${j+1}</span><div><h3>${moments[i].short}</h3><p>${moments[i].summary}</p></div></div>`).join('')}<div class="empty-note"><b>Where we are now:</b> ${moments[available().at(-1)??0].summary}</div><div class="modal-footer"><button class="primary" id="recapExplore">Explore the first moment ↗</button><button class="primary" id="recapLive">I’m caught up ✓</button></div>`);$('#recapExplore').onclick=()=>{$('#modal').close();setTab('timeline');select(ids[0])};$('#recapLive').onclick=()=>{$('#modal').close();jumpLive()}};
function jumpLive(){setTab('timeline');select(available().at(-1)??0)}$('#jumpLive').onclick=jumpLive;$('#liveButton').onclick=jumpLive;$('#prev').onclick=()=>select(Math.max(0,selected-1));$('#next').onclick=()=>select(Math.min(available().at(-1),selected+1));
function updateClock(){const text=fmt(elapsed);$('#clock').textContent=text;$('#playerClock').textContent=text;$('#scrubber').value=elapsed;const i=available().at(-1)??0;$('#playerTitle').textContent=moments[i].short;$('#liveText').textContent=`“${moments[i].quote}”`;$('.live-transcript>span').textContent=`Transcript excerpt · ${moments[i].label}`;renderTimeline();if(tab==='map')renderMap()}
function setPlaying(value){playing=value;$('#play').textContent=playing?'Ⅱ':'▶';$('#play').setAttribute('aria-label',playing?'Pause simulated lecture':'Play simulated lecture')}
$('#play').onclick=()=>{if(elapsed>=3660){elapsed=0;selected=0;updateClock();renderDetail()}setPlaying(!playing)};$('#speed').onclick=()=>{speed=speed===1?5:speed===5?15:1;$('#speed').textContent=`${speed}×`};$('#scrubber').oninput=e=>{elapsed=+e.target.value;selected=available().at(-1)??0;updateClock();renderDetail();if(elapsed>=3660)setPlaying(false)};setInterval(()=>{if(!playing)return;const old=available().length;elapsed=Math.min(3660,elapsed+speed);updateClock();if(available().length!==old){toast('A new concept has joined the timeline.');if(tab==='timeline')select(available().at(-1))}if(elapsed>=3660){setPlaying(false);toast('Lecture complete. Your moments are ready to revisit.')}},1000);
$('#help').onclick=()=>openModal(`<div class="eyebrow">ABOUT THIS PROTOTYPE</div><h2>Find your thread.</h2><p>Recall is a working interaction prototype using CS 690S Lecture 2, September 15, 2026: <b>Limitations of Behavior Cloning</b>, taught by Prof. Scott Niekum.</p><p>The slide images are rendered from your local lecture PDF. Explanations and excerpts are curated from the accompanying transcript. Times marked ≈ are estimated because the transcript does not timestamp every passage.</p><p>Play simulates the lecture clock; it does not play audio or record a microphone. The timeline and concept graph reveal prewritten content as the clock advances. Saved moments and completed study prompts stay in this browser.</p><p>Try Catch me up, select a timeline moment, expand a slide, or explore the concept map.</p>`);const previewTitles=['The big picture','Learning by imitation','','Reinforcement learning','Reward hacking','Learning the reward'];$$('[data-preview]').forEach(b=>b.onclick=()=>{const i=+b.dataset.preview;openModal(`<div class="eyebrow">COURSE LIBRARY · LECTURE ${String(i).padStart(2,'0')}</div><h2>${previewTitles[i]}</h2><p>This prototype brings Lecture 02 to life. The other lectures are shown to illustrate the course-wide workspace; their timelines are not loaded yet.</p><div class="modal-footer"><button class="primary" id="backMoment">Return to Lecture 02 ↗</button></div>`) });$('#currentLecture').onclick=()=>setTab('timeline');$('#course').onclick=()=>openModal(`<div class="eyebrow">YOUR COURSE</div><h2>AI Alignment</h2><p>COMPSCI 690S · Fall 2026 · Prof. Scott Niekum</p><p>Currently exploring Lecture 02: Limitations of Behavior Cloning. This prototype uses one lecture’s slides and transcript to demonstrate live context recovery.</p><div class="modal-footer"><button class="primary" id="backMoment">Continue lecture ↗</button></div>`);renderTimeline();renderDetail();updateClock();setTab('timeline');
